const KEY='tiny-routines-v1';
let state=JSON.parse(localStorage.getItem(KEY)||'null')||{name:'little one',entries:[]};
const $=s=>document.querySelector(s);
const today=()=>new Date().toISOString().slice(0,10);
let selectedDate=today();
const esc=s=>String(s||'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function save(){localStorage.setItem(KEY,JSON.stringify(state));render()}
function formatDate(date=today()){let d=new Date(date+'T12:00:00');return new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(d)}
function shiftDate(amount){let d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()+amount);selectedDate=d.toISOString().slice(0,10);render()}
function formatTime(t){let [h,m]=t.split(':');let d=new Date();d.setHours(h,m);return d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}
function render(){
 $('#displayName').textContent=state.name; $('#babyNameButton').textContent=(state.name[0]||'L').toUpperCase(); $('#todayLabel').textContent=formatDate(selectedDate)+(selectedDate===today()?'':' · history');
 $('#clearToday').textContent=selectedDate===today()?'Clear today':'Clear this day';
 const entries=state.entries.filter(e=>e.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time));
 const feeds=entries.filter(e=>e.type==='feed'), diapers=entries.filter(e=>e.type==='diaper'), sleeps=entries.filter(e=>e.type==='sleep');
 $('#feedsCount').textContent=feeds.length; $('#diaperCount').textContent=diapers.length; $('#wetCount').textContent=diapers.filter(e=>e.kind==='wet'||e.kind==='both').length+' wet'; $('#dirtyCount').textContent=diapers.filter(e=>e.kind==='dirty'||e.kind==='both').length+' dirty';
 let mins=sleeps.reduce((n,e)=>n+(Number(e.duration)||0),0); $('#sleepTotal').textContent=Math.floor(mins/60)+'h '+(mins%60)+'m'; $('#sleepBarFill').style.width=Math.min(100,mins/900*100)+'%';
 let days=[];for(let i=6;i>=0;i--){let d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()-i);let key=d.toISOString().slice(0,10),day=state.entries.filter(e=>e.date===key);days.push({label:d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2),feeds:day.filter(e=>e.type==='feed').length,sleep:day.filter(e=>e.type==='sleep').reduce((n,e)=>n+(Number(e.duration)||0),0),diapers:day.filter(e=>e.type==='diaper').length})};let max=Math.max(1,...days.map(d=>d.feeds));$('#patterns').innerHTML=days.map(d=>`<div class="pattern-day"><span>${d.label}</span><i style="height:${Math.max(8,d.feeds/max*42)}px" title="${d.feeds} feeds"></i><small>${d.feeds}</small></div>`).join('');
 const timeline=$('#timeline'); timeline.classList.toggle('empty-state',!entries.length);
 timeline.innerHTML=entries.length?entries.map(e=>`<div class="timeline-entry"><div class="entry-time">${formatTime(e.time)}</div><div class="entry-rail"><i class="entry-dot"></i></div><div class="entry-body"><button class="delete-entry" data-delete="${e.id}" aria-label="Delete entry">×</button><div class="entry-title">${esc(label(e))}</div><div class="entry-meta">${esc(meta(e))}${e.note?' · '+esc(e.note):''}</div></div></div>`).join(''):`<div class="empty-illustration">☼</div><h3>A quiet start</h3><p>Log a feed, nap, diaper, or note to begin today's rhythm.</p>`;
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{state.entries=state.entries.filter(e=>e.id!==b.dataset.delete);save();toast('Entry removed')});
}
function label(e){return e.type==='feed'?'Feed':e.type==='sleep'?'Sleep':e.type==='diaper'?'Diaper':'Note'}
function meta(e){if(e.type==='feed')return `${e.method||'Feed'}${e.amount?' · '+e.amount+' oz':''}`;if(e.type==='sleep')return `${e.duration||0} minutes`;if(e.type==='diaper')return (e.kind||'wet').replace(/^./,x=>x.toUpperCase());return 'Remembered moment'}
function fields(type){return type==='feed'?'<label>Method<select id="fieldMethod"><option>Breast</option><option>Bottle</option><option>Formula</option></select></label><label>Amount (optional)<input id="fieldAmount" type="number" min="0" step="0.5" placeholder="oz"></label>':type==='sleep'?'<label>Duration (minutes)<input id="fieldDuration" type="number" min="1" required placeholder="e.g. 45"></label>':type==='diaper'?'<label>Type<select id="fieldKind"><option value="wet">Wet</option><option value="dirty">Dirty</option><option value="both">Wet + dirty</option></select></label>':'<p class="subtle" style="margin-top:14px">Capture a sweet moment, a question, or anything you want to remember.</p>'}
 function openModal(type='feed'){ $('#entryType').value=type; $('#dynamicFields').innerHTML=fields(type); $('#entryTime').value=new Date().toTimeString().slice(0,5); $('#modalBackdrop').hidden=false; $('#modalBackdrop').style.display='grid'; $('#entryType').focus() }
 function closeModal(){ $('#modalBackdrop').hidden=true; $('#modalBackdrop').style.display='none' }
 $('#addEntryButton').onclick=()=>openModal(); document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>openModal(b.dataset.quick)); $('#closeModal').onclick=e=>{e.preventDefault();closeModal()}; $('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()}; document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modalBackdrop').hidden)closeModal()}); $('#entryType').onchange=e=>$('#dynamicFields').innerHTML=fields(e.target.value);
 $('#entryForm').onsubmit=e=>{e.preventDefault();let type=$('#entryType').value;let x={id:crypto.randomUUID(),date:selectedDate,time:$('#entryTime').value,type,note:$('#entryNote').value.trim()};if(type==='feed'){x.method=$('#fieldMethod').value;x.amount=$('#fieldAmount').value}else if(type==='sleep')x.duration=$('#fieldDuration').value;else if(type==='diaper')x.kind=$('#fieldKind').value;state.entries.push(x);save();closeModal();toast('Saved to '+(selectedDate===today()?'today':'history'));e.target.reset()};
 $('#clearToday').onclick=()=>{if(confirm('Clear all entries for '+formatDate(selectedDate)+'?')){state.entries=state.entries.filter(e=>e.date!==selectedDate);save();toast('Day cleared')}};
 $('#babyNameButton').onclick=()=>{let n=prompt('What should we call your baby?',state.name);if(n&&n.trim()){state.name=n.trim();save()}};
 const exportData=()=>download('tiny-routines.json',JSON.stringify(state,null,2),'application/json'); const exportCsv=()=>{let rows=[['Date','Time','Type','Details','Note'],...state.entries.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(e=>[e.date,e.time,label(e),meta(e),e.note||''])];download('tiny-routines.csv',rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\\n'),'text/csv')}; $('#exportTop').onclick=exportData; $('#downloadJson').onclick=exportData; $('#downloadCsv').onclick=exportCsv; $('#copyData').onclick=async()=>{try{await navigator.clipboard.writeText(JSON.stringify(state,null,2));toast('Data copied to clipboard')}catch{toast('Copy unavailable in this browser')}};
 $('#prevDay').onclick=()=>shiftDate(-1); $('#nextDay').onclick=()=>shiftDate(1); $('#jumpToday').onclick=()=>{selectedDate=today();render()}; $('#restoreData').onclick=()=>$('#restoreInput').click(); $('#restoreInput').onchange=e=>{let file=e.target.files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let restored=JSON.parse(reader.result);if(!restored||!Array.isArray(restored.entries))throw new Error();state={name:restored.name||'little one',entries:restored.entries};save();toast('Backup restored')}catch{toast('That backup could not be read')}};reader.readAsText(file)};
function download(name,data,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href);toast('Download ready')}
function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
render();
